import type { AuthorityClass, MaataaRenderable } from "@maataa/contracts";
export interface ComponentDefinition<T=unknown>{componentId:string;version:string;category:string;authorityClass:AuthorityClass;validate:(props:unknown)=>props is T;allowedActions?:string[];}
export class ComponentRegistry{private entries=new Map<string,ComponentDefinition>();register(d:ComponentDefinition){const k=`${d.componentId}@${d.version}`;if(this.entries.has(k))throw new Error(`Duplicate component: ${k}`);this.entries.set(k,d);}get(id:string,v:string){return this.entries.get(`${id}@${v}`);}validate(n:MaataaRenderable){const d=this.get(n.component,n.version);if(!d)return {ok:false as const,reason:"UNREGISTERED_COMPONENT"};if(!d.validate(n.props))return {ok:false as const,reason:"INVALID_PROPS"};return {ok:true as const,definition:d};}list(){return [...this.entries.values()];}}
